/**
 * Growing past the chart's sectors by selecting (findings/builder_system_design.md §18, item 7;
 * §20): hexes picked in an empty slot are generated by making the slot's sector, then the
 * systems. It is one request to the server (`POST .../generate` with `makeSectors`), and its
 * Undo is one request (`POST .../sectors/undo-generate`) that takes back every sector made and
 * every hex written, also while the job still runs. A sector is never made without its sixteen
 * subsectors; none is made on its own.
 */
import { reactive } from 'vue';
import { showToast } from '../../shell/toast.ts';
import { holdJob, selectOnMap, tallyOf } from './acts.ts';
import { endFlight, renameFlight, startFlight } from './flight.ts';
import { buildStore, type GrowHandle, type GrowProgress, type JobProgress, type UndoToken } from './seam.ts';
import { cleanName, slotGroups } from './sectors.ts';
import { build, generateTargets, jobToast, plural } from './state.ts';

/** The names typed for the new sectors, by the slot's address; kept while the selection lasts. */
export const growUi = reactive({
    names: {} as Record<string, string>,
    /** The slot whose name is missing or too long, so the pane can put the cursor in its box. */
    want: '',
    /** Goes up each time the name box is asked for, so asking twice for the same slot still moves the cursor. */
    focus: 0,
    /** From the press until the server has answered: nothing is made yet. */
    busy: false,
    error: '',
    /** While the act's job runs: its Undo, which stops the job and takes everything back. */
    undoRunning: null as (() => void) | null,
});

/** The hexes reach into an empty slot: Generate there needs the new sector's name first. */
export function inEmptySlot(keys: readonly string[]): boolean {
    return slotGroups(keys).length > 0;
}

/** Generate was asked for by key or menu on hexes in an empty slot: the pane's name box takes the cursor; nothing is made yet. */
export function askSectorName(keys: readonly string[]): void {
    const first = slotGroups(keys)[0];
    if (!first) return;
    growUi.want = first.slug;
    growUi.focus += 1;
}

/** The store's states, read as the screen's four. */
export function screenProgress(progress: GrowProgress): JobProgress {
    const state = progress.state === 'stopping' || progress.state === 'stopped' || progress.state === 'running' || progress.state === 'done'
        ? progress.state
        : progress.state === 'failed' ? 'done' : 'running';
    return { total: progress.total, done: progress.done, failed: progress.failed, state };
}

/** "the new sector Vell", or "2 new sectors: Vell, Ostra". */
export function madeWords(names: readonly string[]): string {
    return names.length === 1 ? 'the new sector ' + names[0] : plural(names.length, 'new sector', 'new sectors') + ': ' + names.join(', ');
}

/** "the new sector Vell", or "the new sectors Vell and Ostra": what an Undo or a Restore says it took or put back. */
export function sectorsSaid(names: readonly string[]): string {
    if (names.length === 1) return 'the new sector ' + names[0];
    return 'the new sectors ' + names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
}

function said(err: unknown, otherwise: string): string {
    return err instanceof Error && err.message ? err.message : otherwise;
}

/** The one Undo: one request. When the store gives back the token that puts it all back, the toast offers Restore. */
async function takeBack(token: UndoToken, names: readonly string[]): Promise<void> {
    const store = buildStore();
    if (!store) return;
    try {
        const restore = await store.undo(token);
        const message = 'Removed ' + sectorsSaid(names) + ' and every system generated in ' + (names.length === 1 ? 'it' : 'them') + '.';
        if (restore) showToast(message, { action: { label: 'Restore', run: () => { void putBack(restore, names); } } });
        else showToast(message);
    } catch (err) {
        showToast(said(err, 'Undo failed. Try again.'));
    }
}

async function putBack(token: UndoToken, names: readonly string[]): Promise<void> {
    const store = buildStore();
    if (!store) return;
    try {
        await store.undo(token);
        showToast('Restored ' + sectorsSaid(names) + ' and ' + (names.length === 1 ? 'its' : 'their') + ' systems.');
    } catch (err) {
        showToast(said(err, 'Restore failed. Try again.'));
    }
}

/**
 * Make each slot's sector and generate the hexes, as one request. A name that is missing stops
 * the act before anything is sent, and says which. A refusal from the server is said in its own
 * words beside the name boxes, and the selection stays as it was.
 */
export function generateGrowing(keys: readonly string[]): void {
    const store = buildStore();
    if (!store || growUi.busy || build.job) return;
    const slots = slotGroups(keys);
    growUi.error = '';
    growUi.want = '';
    const names: Record<string, string> = {};
    for (const group of slots) {
        const name = cleanName(growUi.names[group.slug] ?? '');
        if (!name) {
            growUi.want = group.slug;
            growUi.focus += 1;
            growUi.error = slots.length === 1 ? 'To generate here, first name the new sector.' : 'To generate here, first name each new sector.';
            return;
        }
        names[group.slug] = name;
    }
    const targets = generateTargets(tallyOf(keys), build.filledToo);
    if (targets.length === 0) return;
    const made = slots.map((group) => names[group.slug]);
    const label = 'Generating ' + plural(targets.length, 'hex', 'hexes');
    build.error = '';
    build.sheetOpen = false;
    build.preview = null;
    let run: GrowHandle;
    try {
        run = store.generateGrowing({
            hexKeys: targets,
            edition: build.choice.engine,
            generator: build.choice.generator,
            roll: 0,
            filledToo: true,
            makeSectors: slots.map((group) => ({ name: names[group.slug], slot: group.slot })),
        }, (progress) => { if (build.job) build.job = { ...screenProgress(progress), label }; });
    } catch (err) {
        growUi.error = said(err, 'Couldn’t create the sector. Try again.');
        return;
    }
    growUi.busy = true;
    build.job = { total: targets.length, done: 0, failed: [], state: 'running', label };
    startFlight(targets);
    holdJob(run.stop);
    let answered = false;
    let undone = false;
    const end = (): void => {
        holdJob(null);
        build.job = null;
        endFlight();
        growUi.undoRunning = null;
    };
    run.accepted.then(
        ({ keys: real, undo }) => {
            answered = true;
            renameFlight(real);
            growUi.busy = false;
            growUi.names = {};
            growUi.undoRunning = () => {
                undone = true;
                growUi.undoRunning = null;
                void takeBack(undo, made);
            };
            // The hexes now have their sector: the selection is theirs.
            selectOnMap(keys.map((key) => real[key] ?? key));
        },
        (err: unknown) => {
            growUi.busy = false;
            end();
            // Nothing was written: the selection and the names stay, and the server's words are shown beside them.
            growUi.error = said(err, 'Couldn’t create the sector. Try again.');
        },
    );
    run.finished.then(
        ({ undo, progress }) => {
            end();
            if (undone) return;
            showToast(jobToast(screenProgress(progress), madeWords(made)), { action: { label: 'Undo', run: () => { void takeBack(undo, made); } } });
        },
        (err: unknown) => {
            end();
            // A refusal before the answer was said beside the names; one after it (the job's watch) is said here.
            if (answered) build.error = said(err, 'The job didn’t finish. Some hexes might still be empty. To fill them, select them and generate again.');
        },
    );
}
